// macOS: borderless click-through panel with a PNG next to the cursor

#import <Cocoa/Cocoa.h>

#include "platform/platform.h"
#include "reaper_plugin_functions.h"
#include "settings.h"

#include "overlay_images.h" // generated by CMake from src/res/*.png

#include <string>

// Optional PNG in UserPlugins overrides the embedded default
static NSImage* LoadOverlayImage(const char* fileName, const unsigned char* data, size_t size)
{
    const char* source = "embedded";
    NSImage* image = nil;
    if (GetResourcePath)
    {
        std::string path = std::string(GetResourcePath()) + "/UserPlugins/" + fileName;
        if (platform::FileExists(path.c_str()))
        {
            image = [[NSImage alloc] initWithContentsOfFile:[NSString stringWithUTF8String:path.c_str()]];
            if (image) source = "file";
        }
    }
    if (!image)
        image = [[NSImage alloc] initWithData:[NSData dataWithBytes:data length:size]];
    NSSize sz = image ? [image size] : NSZeroSize;
    DebugLog("[Drop To Sampler] overlay %s=%s (%s %dx%d)\n", fileName, image ? "OK" : "FAIL", source,
        (int)sz.width, (int)sz.height);
    return image; // retained
}

class CocoaOverlay : public DragOverlay
{
public:
    CocoaOverlay()
    {
        m_insert = LoadOverlayImage("sampler_insert.png", k_sampler_insert_png, sizeof(k_sampler_insert_png));
        m_replace = LoadOverlayImage("sampler_replace.png", k_sampler_replace_png, sizeof(k_sampler_replace_png));
    }

    ~CocoaOverlay() override
    {
        [m_panel orderOut:nil];
        [m_panel release];
        [m_insert release];
        [m_replace release];
    }

    void ShowAtCursor(DropVisualKind kind) override
    {
        NSImage* image = (kind == DropVisual_Replace && m_replace) ? m_replace : m_insert;
        if (!image)
        {
            Hide();
            return;
        }
        EnsurePanel();

        NSSize size = [image size];
        [m_imageView setImage:image];
        [m_imageView setFrame:NSMakeRect(0, 0, size.width, size.height)];

        // Below-right of the cursor; Cocoa screen origin is bottom-left
        NSPoint mouse = [NSEvent mouseLocation];
        [m_panel setFrame:NSMakeRect(mouse.x + 16, mouse.y - 16 - size.height, size.width, size.height) display:YES];
        [m_panel orderFrontRegardless];
    }

    void Hide() override
    {
        [m_panel orderOut:nil];
    }

private:
    void EnsurePanel()
    {
        if (m_panel) return;
        m_panel = [[NSPanel alloc] initWithContentRect:NSMakeRect(0, 0, 32, 32)
                                             styleMask:NSWindowStyleMaskBorderless | NSWindowStyleMaskNonactivatingPanel
                                               backing:NSBackingStoreBuffered
                                                 defer:YES];
        [m_panel setOpaque:NO];
        [m_panel setBackgroundColor:[NSColor clearColor]];
        [m_panel setHasShadow:NO];
        [m_panel setIgnoresMouseEvents:YES];
        [m_panel setLevel:NSStatusWindowLevel];
        [m_panel setReleasedWhenClosed:NO];
        [m_panel setCollectionBehavior:NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorTransient];

        m_imageView = [[NSImageView alloc] initWithFrame:NSMakeRect(0, 0, 32, 32)];
        [m_imageView setImageScaling:NSImageScaleNone];
        [[m_panel contentView] addSubview:m_imageView];
        [m_imageView release]; // owned by the content view
    }

    NSPanel* m_panel = nil;
    NSImageView* m_imageView = nil;
    NSImage* m_insert = nil;
    NSImage* m_replace = nil;
};

std::unique_ptr<DragOverlay> DragOverlay::Create()
{
    return std::unique_ptr<DragOverlay>(new CocoaOverlay());
}
